Let $f_{\bm{\theta}}$, $G$, $\bm{x}$ and $\bm{y}_{\mathcal{D}}$ as above, $\mathcal{L}$ density of a $\mathcal{N}\left(\bm{z}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \bm{I}_{n_L \times k}\right)$. Assume a common variance for the last hidden layer of the BNN and the likelihood, distributed as an Inverse-Gamma 
    \begin{equation*}
        \sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, \ \sigma^2 \sim \mathcal{IG}\left(a, b\right),
    \end{equation*}
    with
    \begin{equation} 
        a > \frac{1}{2}, \ b > \left(1 + \frac{\varepsilon + 2}{2\varepsilon + 2}\right) \left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2, \text{ for any } \varepsilon < 1/\left\lVert\bm{K}'(\bm{x})\right\rVert_{\mathrm{op}}. 
    \end{equation}
    Then, there exists a constant $c > 0$, independent of $\left(n_l\right)_{l = 1}^{L - 1}$, such that
    \begin{equation*}
        \mathcal{W}_{1}\left(f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}, G(\bm{x}) \, | \, \mathcal{D}\right) \leq \frac{c}{\sqrt{n_{min}}}.
    \end{equation*}

Given $f_{\bm{\theta}}$, $G$, $\bm{x}$, $\bm{y}_{\mathcal{D}}$ and $\mathcal{L}$ as in C.2, and assuming $\sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 =$ $= \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$ exist some constants
	\begin{equation*}
		c_i\left(\mathcal{D}, \bm{\varphi}, (\bm{\sigma}_l)_{l = 1}^{L - 1}, n_L\right) > 0, \,i = 0, \dots, 4, \text{ independent of } \left(n_l\right)_{l = 1}^{L - 1}, \sigma^2,
	\end{equation*}
	such that,
	\begin{equation*}
		\mathcal{W}_{1}\left(f_{\bm{\theta}}(\bm{x}) \, | \, (\mathcal{D}, \sigma^2), G(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)\right) \leq h(\sigma^2) \frac{c_0}{\sqrt{n_{min}}},
	\end{equation*}
	with
	\begin{equation*}
		h(\sigma^2) = c_1 \left(\sigma^2\right)^{1/2} \operatorname{exp}\left(\frac{\left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2}{\sigma^2}\right) \left(c_2 + c_3 \left(\sigma^2\right)^{1/2} + c_4 \left(\sigma^2\right)^{- n_L k / 2} \operatorname{exp}\left(\frac{\left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2}{\sigma^2}\right)\right).
	\end{equation*}

Given $f_{\bm{\theta}}$, $G$ and $\bm{x}$ as in 2.8, $p \geq 1$, and assuming $\sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 =$ $= \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$, there exists a constant
	\begin{equation*}
		c\left(p, \bm{x}, \bm{\varphi}, (\bm{\sigma}_l)_{l = 1}^{L - 1}\right) > 0, \text{ independent of } \left(n_l\right)_{l = 1}^L, \sigma^2,
	\end{equation*}
	such that
	\begin{equation*}
		\mathcal{W}_{p}\left(f_{\bm{\theta}}(\bm{x}) \, | \, \sigma^2, G(\bm{x}) \, | \, \sigma^2\right) \leq \sigma c \sqrt{n_L} \sum_{l = 1}^{L - 1} \frac{1}{\sqrt{n_l}},
	\end{equation*}

Given $f_{\bm{\theta}}$, $G$, $\bm{x}$, $\bm{y}_{\mathcal{D}}$ and $\mathcal{L}$ as in C.2, assuming $\sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 =$ $= \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$, $\bm{K}'(\bm{x}) \in \operatorname{Sym}_+^{k}$ (rescaled NNGP kernel), and 
	\begin{equation*}
		\bm{v} \sim G(\bm{x}) \, | \, \sigma^2, \, \bm{w} \sim f_{\bm{\theta}}(\bm{x}) \, | \, \sigma^2,
	\end{equation*}
	$\forall\,\,\,\,\,\,\,\, \varepsilon < 1/\left\lVert\bm{K}'(\bm{x})\right\rVert_{\mathrm{op}}$ it holds
	\begin{equation*}


		\begin{aligned}
			c_1 \cdot \left(\sigma^2\right)^{- n_L k / 2} \operatorname{exp}\left(-\frac{\left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2}{\sigma^2}\right) \leq \ & \mathbb{E}_{\kern-0.5pt}\left[\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})\right] \leq c_2 \cdot \left(\sigma^2\right)^{- n_L k / 2} \operatorname{exp}\left(-\frac{1}{2 \sigma^2} \frac{\varepsilon}{\varepsilon + 1} \left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2\right), \\
			c_3 \operatorname{exp}\left(-\frac{\left\lVert\bm{y}_{\mathcal{D}}\right\rVert_F^2}{\sigma^2}\right) \leq \ & \mathbb{E}_{\kern-0.5pt}\left[\mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})\right] \leq c_4 \cdot \left(\sigma^2\right)^{- n_L k / 2},
		\end{aligned}
	\end{equation*}
	where $n_{min} = \min_{l = 1, \dots, L - 1} n_l$ is sufficiently large and the constants depend on $\bm{x}, \bm{\varphi}$, $\left(\bm{\sigma}_l\right)_{l = 1}^{L - 1}, n_L$.

Given $f_{\bm{\theta}}$ BNN, with architecture $\bm{\alpha} = (\bm{n}, \bm{\varphi})$, $\bm{\varphi}$ collection of Lipschitz activation functions, prior distribution on $\bm{\theta}$ as in 4, $G$ Gaussian process as in 6, $\bm{x}$, $\bm{y}_{\mathcal{D}}$ as in 3.2, and a Gaussian likelihood function $\mathcal{L} \sim \mathcal{N}\left(\bm{z}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \bm{I}_{n_L \times k}\right)$, exists a constant
	\begin{equation*}
		c\left(\mathcal{D}, \bm{\varphi}, \bm{\sigma}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, n_L\right) > 0, \text{ independent of } \left(n_l\right)_{l = 1}^{L - 1},
	\end{equation*}
	such that,
	\begin{equation*}
		\mathcal{W}_{1}\left(f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}, G(\bm{x}) \, | \, \mathcal{D}\right) \leq c \frac{1}{\sqrt{n_{min}}},
	\end{equation*}
	for all $\displaystyle n_{min} \coloneqq \min_{l = 1, \dots, L - 1} n_l$ sufficiently large.

Let $f_{\bm{\theta}}$ BNN, with architecture $\bm{\alpha} = (\bm{n}, \bm{\varphi})$, $\bm{\varphi}$ collection of Lipschitz activation functions, a prior on $\bm{\theta}$ as in 4, $\left(G^{(l)}\right)_{l = 1}^L$ Gaussian processes as in 6 and an input set $\bm{x} \in \mathbb{R}^{d_{\mathrm{in} \times m}}$. Then, $\forall\,\,\,\,\,\,\,\, l \in [L]$ exists a constant $c > 0$ independent of $\left(n_j\right)_{j = 1}^l$, such that,
    \begin{equation} 
        \mathcal{W}_{p}\left(f_{\bm{\theta}}^{(l)}(\bm{x}), G^{(l)}(\bm{x})\right) \leq c \sqrt{n_l} \sum_{j = 1}^{l - 1} \frac{1}{\sqrt{n_j}}.
    \end{equation}

Let $\mathcal{L}$ be a Gaussian likelihood, $\mathcal{L} \sim \mathcal{N}\left(\bm{z}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \bm{I}_{n_L \times k}\right)$, it holds
	\begin{equation*}
		\left\lVert\mathcal{L}\right\rVert_{\infty} = \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}} \quad \text{and} \quad \operatorname{Lip}\left(\mathcal{L}\right) = \frac{e^{-1/2}}{\sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}} \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}}.
	\end{equation*}

Given two random variables $\bm{x}$, $\bm{y}$ with values in $\mathbb{R}^S$ and a positive constant $a$, $\forall\,\,\,\,\,\,\,\, p \geq 1$, it holds
	\begin{equation} 
		\mathcal{W}_{p}\left(a \bm{x}, a \bm{y}\right) = a \mathcal{W}_{p}\left(\bm{x}, \bm{y}\right).
	\end{equation}

Let $\mu$, $\widetilde{\mu}$ be probability measures on $(\mathbb{R}^S, \left\lVert\cdot\right\rVert)$ for some finite set $S$ and finite moments of order $p \geq 1$.
	Fix $g: \mathbb{R}^S \to \mathbb{R}^+$ be a uniformly bounded (by $\left\lVert g\right\rVert_\infty$) Lipschitz continuous map (with constant $\operatorname{Lip}\left(g\right)$), such that
	\begin{equation*}
		\mu(g) \coloneqq \int_{\mathbb{R}^S} g(\bm{z}) d\mu(\bm{z}) > 0 \quad \text{and} \quad \widetilde{\mu}(g) >0.
	\end{equation*}
	Defining the probability measures $\mu_g \ll \mu$ and $\widetilde{\mu}_g \ll \widetilde{\mu}$, with respective densities $\frac{d\mu_g}{d\mu} \coloneqq \frac{g}{\mu(g)}$ and $\frac{d\widetilde{\mu}_g}{d\widetilde{\mu}} \coloneqq \frac{g}{\widetilde{\mu}(g)}$, it holds
	\begin{equation} 
		\mathcal{W}_{1}\left(\widetilde{\mu}_g, \mu_g\right) \leq \frac{1}{\mu(g)} \left(\operatorname{Lip}\left(g\right) m_{p / (p - 1)}(\mu) + \left(1 + \frac{m_1(\mu) \operatorname{Lip}\left(g\right)}{\widetilde{\mu}(g)}\right) \left\lVert g\right\rVert_{\infty}\right) \mathcal{W}_{p}\left(\widetilde{\mu}, \mu\right).
	\end{equation}

Let us consider two Markov kernels $(\mu(s))_{s \in \mathbb{R}^+}$, $(\widetilde{\mu}(s))_{s \in \mathbb{R}^+}$ with source $\mathbb{R}^+$ and target $\mathbb{R}^T$ and a measure $\nu$ on $\mathbb{R}^+$ ($T$ finite set).
            Defining the probability measures on $\mathbb{R}^T$ such that, $\forall\,\,\,\,\,\,\,\, B \in \mathcal{B}\left(\mathbb{R}^T\right)$,
            \begin{equation*}
                \mu(B) \coloneqq \int_{\mathbb{R}^+} \mu(s)(B) d\nu(s), \quad \widetilde{\mu}(B) \coloneqq \int_{\mathbb{R}^+} \widetilde{\mu}(s)(B) d\nu(s),
            \end{equation*}
            the following convexity property for the distance $\mathcal{W}_1$ holds: 
            \begin{equation} 
                \mathcal{W}_{1}\left(\mu, \widetilde{\mu}\right) \leq \int_{\mathbb{R}^+} \mathcal{W}_{1}\left(\mu(s), \widetilde{\mu}(s)\right) d\nu(s).
            \end{equation}
